// Des: Tests feed command: opt-in chats, incremental export, keys
// Flo: in-memory store with messages > build records > save marks the last id > second build only sees new messages
// I/O: temp dir + memory db > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const feed = @import("ct-comm-feed.zig"); const data = @import("st-stat-data.zig"); const confz = @import("cf-conf-load.zig"); const T = std.testing;
test "record: url and id are stable hashes, text capped, seconds become ms, empty is skipped" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); var cfg: confz.Conf = .{}; const rec = (try feed.recoOf(alo, cfg, "Bán xe HN", "Ann", " Fortuner 2017 giá 520tr 0966.353.678 ", 1_795_000_000)).?; try T.expectEqualStrings("zalo", rec.kind); try T.expectEqualStrings("Bán xe HN", rec.src); try T.expectEqualStrings("Ann", rec.auth); try T.expectEqualStrings("private", rec.role); try T.expectEqual(@as(i64, 1_795_000_000_000), rec.posted); try T.expect(std.mem.startsWith(u8, rec.url, "https://chat.zalo.me/c/")); try T.expect(std.mem.endsWith(u8, rec.url, rec.id)); try T.expect(std.mem.find(u8, rec.url, "Bán") == null); try T.expect(std.mem.find(u8, rec.text, "0966.353.678") != null); const again = (try feed.recoOf(alo, cfg, "Bán xe HN", "Ann", " Fortuner 2017 giá 520tr 0966.353.678 ", 1_795_000_000)).?; try T.expectEqualStrings(rec.id, again.id); const other = (try feed.recoOf(alo, cfg, "Bán xe HN", "Ann", "different", 1_795_000_000)).?; try T.expect(!std.mem.eql(u8, rec.id, other.id)); try T.expect((try feed.recoOf(alo, cfg, "c", "w", "   ", 5)) == null); cfg.feed_text_maxz = 200; const long: [600]u8 = @splat('a'); const cut = (try feed.recoOf(alo, cfg, "c", "w", &long, 5)).?; try T.expect(cut.text.len <= 200); const msec = (try feed.recoOf(alo, cfg, "c", "w", "x", 1_795_000_000_000)).?; try T.expectEqual(@as(i64, 1_795_000_000_000), msec.posted); }
test "build takes only listed chats, save writes one jsonl and marks the last id, next build sees only new messages" { var sto = try data.Stor.open(T.allocator, ":memory:"); defer sto.close(); var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); try sto.msgAdd("Group A", "Ann", "Toyota Fortuner 2017 giá 520 triệu", 1000); try sto.msgAdd("Group A", "Bob", "Cần mua Mazda CX-5", 2000); try sto.msgAdd("Group A", "Bob", "  ", 3000); try sto.msgAdd("Family", "Mom", "private words", 4000); var cfg: confz.Conf = .{}; cfg.feed_chat_list = &.{"Group A"}; const b1 = try feed.feedBuil(alo, &sto, cfg); try T.expectEqual(@as(u32, 2), b1.cntz); try T.expectEqual(@as(u32, 1), b1.skpz); try T.expect(std.mem.find(u8, b1.body, "private words") == null); var lines: u32 = 0; var itr = std.mem.splitScalar(u8, std.mem.trim(u8, b1.body, "\n"), '\n'); while (itr.next()) |ln| { const rec = try std.json.parseFromSliceLeaky(feed.Reco, alo, ln, .{ .ignore_unknown_fields = true }); try T.expectEqualStrings("zalo", rec.kind); try T.expectEqualStrings("Group A", rec.src); lines += 1; } try T.expectEqual(@as(u32, 2), lines);
var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}/social-in", .{tmpz.sub_path}); const path = try feed.feedSave(alo, T.io, &sto, b1, dirz, 99); try T.expect(std.mem.endsWith(u8, path, "za-99.jsonl")); const back = try std.Io.Dir.cwd().readFileAlloc(T.io, path, alo, .limited(1 << 20)); try T.expectEqualStrings(b1.body, back);
const b2 = try feed.feedBuil(alo, &sto, cfg); try T.expectEqual(@as(u32, 0), b2.cntz); try sto.msgAdd("Group A", "Cy", "Bán Ford Ranger 2019", 5000); const b3 = try feed.feedBuil(alo, &sto, cfg); try T.expectEqual(@as(u32, 1), b3.cntz); try T.expect(std.mem.find(u8, b3.body, "Ford Ranger") != null); try T.expectError(error.BadConfig, feed.feedSave(alo, T.io, &sto, b3, "", 100)); const b4 = try feed.feedBuil(alo, &sto, cfg); try T.expectEqual(@as(u32, 1), b4.cntz); }
test "config: feed keys default to opt-in nothing, bad values are refused" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const alo = aren.allocator(); const conf0: confz.Conf = .{}; try T.expectEqual(@as(usize, 0), conf0.feed_chat_list.len); try T.expectEqual(@as(u32, 500), conf0.feed_item_maxz); const good = try confz.confParse(alo, "{\"feed_chat_list\": [\"Group A\"]}"); try T.expectEqual(@as(usize, 1), good.feed_chat_list.len); const bads = [_][]const u8{ "{\"feed_chat_list\": [\"  \"]}", "{\"feed_item_maxz\": 0}", "{\"feed_item_maxz\": 5001}", "{\"feed_text_maxz\": 5}" }; for (bads) |badz| try T.expectError(error.BadConfig, confz.confParse(alo, badz)); }
